mapper.select:
SELECT date, time, code_number, product_name, in_quantity, out_quantity,
       target_system, specification, price, receiver, remark
FROM ${table}
WHERE deleted_at IS NULL

    AND (target_system IS NULL OR target_system != 'SOT')


    AND date >= #{startDate}


    AND date <= #{endDate}



    AND in_quantity > 0



    AND out_quantity > 0


ORDER BY date ASC, time ASC, id ASC

SELECT date, time, code_number, product_name, out_quantity, specification, price
FROM stockinout_data
WHERE deleted_at IS NULL
  AND out_quantity > 0
  AND target_system = #{system}
  AND date >= #{startDate}
  AND date <= #{endDate}
ORDER BY date ASC, time ASC, id ASC

SELECT id, date, code_number, product_name, in_quantity, specification, price
FROM ${table}
WHERE date BETWEEN #{startDate} AND #{endDate}
  AND in_quantity > 0
ORDER BY date ASC, time ASC, id ASC
